package run.halo.starter;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import javax.imageio.ImageIO;
import org.junit.jupiter.api.Test;
import reactor.core.publisher.Mono;
import com.fasterxml.jackson.databind.ObjectMapper;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
class OfficialAccountContentTest {
 @Test void webpCoverIsConvertedToJpegWithoutGlobalImageIoRegistration()throws Exception{try(var stream=getClass().getResourceAsStream("/officialaccount/pink.webp")){assertNotNull(stream);byte[] jpeg=OfficialAccountContent.jpeg(stream.readAllBytes());assertEquals(255,jpeg[0]&255);assertEquals(216,jpeg[1]&255);var image=ImageIO.read(new java.io.ByteArrayInputStream(jpeg));assertEquals(8,image.getWidth());assertEquals(6,image.getHeight());}}
 @Test void sanitizeAndResolveImagesWithoutScriptsOrTrackingStyles(){var doc=OfficialAccountContent.clean("<script>secret()</script><p onclick='steal()' style='background:url(https://bad.example)'>你好</p><img data-src='/upload/a.png' onerror='steal()'><video src='secret.mp4'></video>","https://blog.example/posts/a");assertFalse(doc.html().contains("steal"));assertFalse(doc.html().contains("bad.example"));assertFalse(doc.html().contains("<video"));assertTrue(doc.text().contains("阅读原文"));assertEquals("https://blog.example/upload/a.png",doc.selectFirst("img").attr("src"));}
 @Test void unsafeInlineImageIsRejectedBeforeAnyNetworkRequest(){var api=mock(OfficialAccountApi.class);var content=new OfficialAccountContent(api);assertThrows(IllegalArgumentException.class,()->content.prepare("account","<img src='http://127.0.0.1/secret'>","https://blog.example/","","","thumb").block());verifyNoInteractions(api);}
 @Test void imagesAreReuploadedAndCoverUsesPermanentMaterial()throws Exception{var api=mock(OfficialAccountApi.class);var image=new BufferedImage(20,20,BufferedImage.TYPE_INT_RGB);var out=new ByteArrayOutputStream();ImageIO.write(image,"png",out);when(api.image(anyString(),anyString())).thenReturn(Mono.just(out.toByteArray()));var mapper=new ObjectMapper();when(api.upload(eq("account"),any(byte[].class),eq(false))).thenReturn(Mono.just(mapper.readTree("{\"url\":\"https://mmbiz.qpic.cn/body.jpg\"}")));when(api.upload(eq("account"),any(byte[].class),eq(true))).thenReturn(Mono.just(mapper.readTree("{\"media_id\":\"permanent-cover\"}")));var prepared=new OfficialAccountContent(api).prepare("account","<h2>文章</h2><img src='/a.png'><p>正文</p>","https://blog.example/post","","","").block();assertTrue(prepared.html().contains("https://mmbiz.qpic.cn/body.jpg"));assertTrue(prepared.html().contains("line-height:1.8"));assertEquals("permanent-cover",prepared.thumbMediaId());verify(api).upload(eq("account"),any(byte[].class),eq(true));verify(api).upload(eq("account"),any(byte[].class),eq(false));}
 @Test void missingCoverIsExplicitAndImageConversionProducesBoundedJpeg()throws Exception{var api=mock(OfficialAccountApi.class);assertThrows(IllegalArgumentException.class,()->new OfficialAccountContent(api).prepare("account","<p>正文</p>","https://blog.example/post","","","").block());assertThrows(IllegalArgumentException.class,()->OfficialAccountContent.jpeg(new byte[]{1,2,3}));var image=new BufferedImage(80,80,BufferedImage.TYPE_INT_ARGB);var out=new ByteArrayOutputStream();ImageIO.write(image,"png",out);byte[] jpeg=OfficialAccountContent.jpeg(out.toByteArray());assertTrue(jpeg.length<1024*1024);assertEquals(80,ImageIO.read(new java.io.ByteArrayInputStream(jpeg)).getWidth());}
}
